WITH latest_match AS (SELECT s.id, s.country, s.signup_date, s.is_active, s.credit_limit, s.age, x.session_country, x.device FROM customers s LEFT JOIN LATERAL (SELECT c.country AS session_country, c.device FROM sessions c WHERE c.customer_id = s.id ORDER BY c.started_at DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT CASE WHEN credit_limit >= 14700 THEN 'HIGH' ELSE 'LOW' END AS credit_limit_tier, session_country, CORR(credit_limit, age) AS corr_credit_limit_age, STDDEV_SAMP(credit_limit) AS credit_limit_stddev FROM latest_match GROUP BY CASE WHEN credit_limit >= 14700 THEN 'HIGH' ELSE 'LOW' END, session_country ORDER BY credit_limit_tier NULLS LAST;
